insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('c1000000-0000-0000-0000-000000000001', 'ukmla', '848f142f-b679-413e-a070-ffe4ceca257b',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('c1000000-0000-0000-0000-000000000001', 'A', 'Arrange an urgent outpatient exercise tolerance test to confirm ischaemia before starting treatment', false, 'Ruled out because a STEMI is a medical emergency requiring immediate reperfusion, not deferred outpatient functional testing.', 1),
('c1000000-0000-0000-0000-000000000001', 'B', 'Administer intravenous thrombolysis only, without considering primary PCI, as this is first-line for all STEMI', false, 'Ruled out because primary PCI, not thrombolysis, is the preferred reperfusion strategy where it can be delivered within the recommended time window.', 2),
('c1000000-0000-0000-0000-000000000001', 'C', 'Give aspirin 300mg and a second antiplatelet immediately, and arrange emergency transfer for primary percutaneous coronary intervention', true, 'Correct. This ECG shows an anterior STEMI (LAD territory); immediate dual antiplatelet loading and emergency reperfusion via primary PCI is the guideline-recommended strategy when it can be delivered promptly.', 3),
('c1000000-0000-0000-0000-000000000001', 'D', 'Start a beta-blocker and arrange routine cardiology outpatient review', false, 'Ruled out because this does not address the immediate life-threatening emergency of an evolving STEMI, which requires urgent reperfusion.', 4),
('c1000000-0000-0000-0000-000000000001', 'E', 'Give high-flow oxygen at 15L/min via non-rebreathe mask regardless of saturation, then reassess in 4 hours', false, 'Ruled out because oxygen should be titrated to a target saturation of 94-98% rather than given routinely to a normoxic patient, and any delay to reperfusion is unacceptable.', 5),
('c1000000-0000-0000-0000-000000000002', 'A', 'Start an appropriate parenteral anticoagulant (dose-adjusted for renal function) and a second antiplatelet, then calculate a GRACE score to guide timing of angiography', true, 'Correct. NSTEMI is managed with dual antiplatelet therapy and anticoagulation, with risk stratification (e.g. GRACE score) determining the urgency of angiography.', 1),
('c1000000-0000-0000-0000-000000000002', 'B', 'Give thrombolysis immediately as she has a positive troponin', false, 'Ruled out because thrombolysis is not indicated in NSTEMI; it is reserved for STEMI when timely PCI is unavailable.', 2),
('c1000000-0000-0000-0000-000000000002', 'C', 'Discharge home with GP follow-up as her ECG shows no ST elevation', false, 'Ruled out because a significantly elevated troponin with ischaemic ECG changes confirms NSSTEMI, which requires admission and risk-stratified management, not discharge.', 3),
('c1000000-0000-0000-0000-000000000002', 'D', 'Withhold all antiplatelet and anticoagulant therapy until renal function is reassessed, as she has chronic kidney disease', false, 'Ruled out because renal impairment requires dose adjustment of anticoagulants rather than complete withholding, as untreated ACS carries a high risk of harm.', 4),
('c1000000-0000-0000-0000-000000000002', 'E', 'Start high-dose diuretic therapy as the immediate priority', false, 'Ruled out because there is no description of fluid overload here, and diuretics do not address the underlying coronary event.', 5),
('c1000000-0000-0000-0000-000000000003', 'A', 'Discharge immediately as the ECG and troponin are normal', false, 'Ruled out because a single normal troponin taken shortly after symptom onset does not exclude myocardial infarction; a repeat test is needed.', 1),
('c1000000-0000-0000-0000-000000000003', 'B', 'Arrange elective outpatient cardiology review in 6 weeks without further inpatient testing', false, 'Ruled out because acute chest pain with an elevated pre-test probability of ACS should not be discharged without further serial testing to exclude MI first.', 2),
('c1000000-0000-0000-0000-000000000003', 'C', 'Start treatment-dose anticoagulation empirically while awaiting further tests', false, 'Ruled out because anticoagulation is not indicated without a confirmed diagnosis of ACS or another thrombotic condition.', 3),
('c1000000-0000-0000-0000-000000000003', 'D', 'Admit for serial ECGs and a repeat troponin at the recommended interval to safely rule out myocardial infarction', true, 'Correct. A single early troponin does not exclude MI; serial troponin testing per the local high-sensitivity assay protocol is required before safe discharge can be considered.', 4),
('c1000000-0000-0000-0000-000000000003', 'E', 'Perform immediate coronary angiography without further non-invasive testing', false, 'Ruled out because invasive angiography is not the first step for undifferentiated low-risk chest pain before serial troponin testing.', 5),
('c1000000-0000-0000-0000-000000000004', 'A', 'Give further sublingual GTN to relieve ongoing chest pain', false, 'Ruled out because further nitrates will worsen hypotension in a preload-dependent right ventricle and are contraindicated here.', 1),
('c1000000-0000-0000-0000-000000000004', 'B', 'Start a loop diuretic to reduce preload', false, 'Ruled out because reducing preload further would worsen hypotension in RV infarction.', 2),
('c1000000-0000-0000-0000-000000000004', 'C', 'Commence an ACE inhibitor immediately to reduce afterload', false, 'Ruled out because afterload-reducing agents would worsen hypotension in this preload-dependent state.', 3),
('c1000000-0000-0000-0000-000000000004', 'D', 'Sit the patient upright and give high-dose opioid analgesia', false, 'Ruled out because an upright position and opioids both reduce venous return/preload, worsening hypotension in RV infarction.', 4),
('c1000000-0000-0000-0000-000000000004', 'E', 'Stop nitrates and give an intravenous fluid bolus to support right ventricular preload', true, 'Correct. In right ventricular infarction the RV is preload-dependent; nitrates should be stopped and IV fluids given to maintain filling pressures.', 5),
('c1000000-0000-0000-0000-000000000005', 'A', 'Ventricular septal rupture', false, 'Ruled out because VSD classically produces a harsh pansystolic murmur at the left sternal edge with a palpable thrill, not an apical murmur radiating to the axilla.', 1),
('c1000000-0000-0000-0000-000000000005', 'B', 'Papillary muscle rupture causing acute severe mitral regurgitation', true, 'Correct. Papillary muscle rupture typically occurs days after inferior MI and presents with acute pulmonary oedema and a new apical pansystolic murmur radiating to the axilla.', 2),
('c1000000-0000-0000-0000-000000000005', 'C', $x$Dressler's syndrome (post-MI pericarditis)$x$, false, $x$Ruled out because Dressler's syndrome presents with pleuritic pain and a pericardial friction rub weeks later, not acute pulmonary oedema with a new murmur.$x$, 3),
('c1000000-0000-0000-0000-000000000005', 'D', 'Re-infarction of the same territory', false, 'Ruled out because re-infarction would not typically produce a new murmur.', 4),
('c1000000-0000-0000-0000-000000000005', 'E', 'Free wall rupture with cardiac tamponade', false, 'Ruled out because free wall rupture typically causes sudden cardiovascular collapse or PEA arrest from tamponade, not a new murmur with pulmonary oedema.', 5),
('c1000000-0000-0000-0000-000000000006', 'A', 'Benzodiazepines', false, 'Ruled out because benzodiazepines help reduce the sympathetic overdrive associated with cocaine toxicity and can be used safely.', 1),
('c1000000-0000-0000-0000-000000000006', 'B', 'Beta-blockers', true, 'Correct. Beta-blockers are avoided in cocaine-associated chest pain because unopposed alpha-adrenergic stimulation can worsen coronary vasospasm and hypertension.', 2),
('c1000000-0000-0000-0000-000000000006', 'C', 'Aspirin', false, 'Ruled out because aspirin remains standard therapy for suspected ACS regardless of the cocaine trigger.', 3),
('c1000000-0000-0000-0000-000000000006', 'D', 'Glyceryl trinitrate', false, 'Ruled out because nitrates can help relieve cocaine-associated coronary vasospasm and are not contraindicated.', 4),
('c1000000-0000-0000-0000-000000000006', 'E', 'Primary PCI if STEMI is confirmed', false, 'Ruled out because primary PCI remains indicated for STEMI even when cocaine-associated.', 5),
('c1000000-0000-0000-0000-000000000007', 'A', 'Perform immediate emergency electrical cardioversion', false, 'Ruled out because emergency cardioversion is reserved for haemodynamically unstable AF, not this stable presentation.', 1),
('c1000000-0000-0000-0000-000000000007', 'B', 'Give intravenous adenosine', false, 'Ruled out because adenosine is used to terminate SVT, not AF.', 2),
('c1000000-0000-0000-0000-000000000007', 'C', 'Withhold anticoagulation entirely because AF has been present for only 2 days', false, 'Ruled out because anticoagulation decisions are based on stroke risk score, not the duration of AF, since true onset is often uncertain.', 3),
('c1000000-0000-0000-0000-000000000007', 'D', 'Start a beta-blocker for rate control and assess her stroke risk (e.g. CHA2DS2-VASc score) to guide anticoagulation', true, 'Correct. Rate control is first-line for stable AF, alongside formal stroke risk assessment to guide anticoagulation decisions.', 4),
('c1000000-0000-0000-0000-000000000007', 'E', 'Start digoxin monotherapy as first-line rate control in this mobile, otherwise well patient', false, 'Ruled out because a beta-blocker or rate-limiting calcium channel blocker is preferred first-line in most patients; digoxin is generally reserved for sedentary patients or those with heart failure.', 5),
('c1000000-0000-0000-0000-000000000008', 'A', 'Emergency synchronised electrical cardioversion under sedation', true, 'Correct. Adverse features (shock, altered consciousness, ischaemia) in a tachyarrhythmia mandate emergency synchronised cardioversion.', 1),
('c1000000-0000-0000-0000-000000000008', 'B', 'Intravenous beta-blocker for rate control, then reassess in 1 hour', false, 'Ruled out because rate control alone is insufficient when adverse features indicate instability; urgent rhythm correction is needed.', 2),
('c1000000-0000-0000-0000-000000000008', 'C', 'Oral anticoagulation followed by elective cardioversion in 4 weeks', false, 'Ruled out because this delayed approach is inappropriate for an unstable patient requiring immediate treatment.', 3),
('c1000000-0000-0000-0000-000000000008', 'D', 'Intravenous adenosine', false, 'Ruled out because adenosine is not effective for AF and is used for SVT.', 4),
('c1000000-0000-0000-0000-000000000008', 'E', 'Vagal manoeuvres such as carotid sinus massage', false, 'Ruled out because vagal manoeuvres are ineffective for AF and are used for SVT.', 5),
('c1000000-0000-0000-0000-000000000009', 'A', 'Give intravenous adenosine as first-line, as it is safe in all broad complex tachycardias', false, 'Ruled out because adenosine can be dangerous in VT and should not be relied upon to distinguish VT from SVT.', 1),
('c1000000-0000-0000-0000-000000000009', 'B', 'Give a calcium channel blocker such as verapamil', false, 'Ruled out because verapamil can precipitate haemodynamic collapse in VT and is contraindicated.', 2),
('c1000000-0000-0000-0000-000000000009', 'C', 'Treat as ventricular tachycardia with intravenous amiodarone, given the history of prior MI and regular broad complex tachycardia', true, 'Correct. In a broad complex tachycardia with structural heart disease, VT should be assumed until proven otherwise and treated with IV amiodarone.', 3),
('c1000000-0000-0000-0000-000000000009', 'D', 'Reassure and discharge as he is currently haemodynamically stable', false, 'Ruled out because VT is life-threatening even when currently stable and requires treatment, not discharge.', 4),
('c1000000-0000-0000-0000-000000000009', 'E', 'Perform vagal manoeuvres only and observe', false, 'Ruled out because vagal manoeuvres are ineffective for VT and would only delay appropriate treatment.', 5),
('c1000000-0000-0000-0000-000000000010', 'A', 'Start an oral beta-blocker to stabilise the rhythm', false, 'Ruled out because beta-blockers would worsen bradycardia and are contraindicated here.', 1),
('c1000000-0000-0000-0000-000000000010', 'B', 'Give intravenous adenosine', false, 'Ruled out because adenosine is not indicated in bradyarrhythmia.', 2),
('c1000000-0000-0000-0000-000000000010', 'C', 'Reassure and observe, as complete heart block after inferior MI is usually benign and needs no intervention', false, 'Ruled out because immediate treatment of symptomatic bradycardia with haemodynamic compromise is required regardless of the usually transient nature of this complication.', 3),
('c1000000-0000-0000-0000-000000000010', 'D', 'Perform immediate synchronised cardioversion', false, 'Ruled out because cardioversion treats tachyarrhythmias, not bradycardia.', 4),
('c1000000-0000-0000-0000-000000000010', 'E', 'Give intravenous atropine and arrange for transcutaneous or transvenous pacing if there is inadequate response', true, 'Correct. First-line treatment of symptomatic bradycardia is atropine, with pacing if response is inadequate.', 5),
('c1000000-0000-0000-0000-000000000011', 'A', 'Intravenous amiodarone as first-line, as it is safe in all broad complex tachycardias', false, 'Ruled out because amiodarone can further prolong the QT interval and worsen torsades.', 1),
('c1000000-0000-0000-0000-000000000011', 'B', 'Oral beta-blocker only, with no need to stop the causative drugs', false, 'Ruled out because the causative QT-prolonging drugs must be stopped or reviewed to prevent recurrence.', 2),
('c1000000-0000-0000-0000-000000000011', 'C', 'Intravenous magnesium sulfate and correction of electrolyte abnormalities, stopping the QT-prolonging drugs', true, 'Correct. First-line treatment of torsades de pointes is IV magnesium, correcting hypokalaemia, and stopping causative drugs.', 3),
('c1000000-0000-0000-0000-000000000011', 'D', 'Synchronised cardioversion only, without correcting electrolytes', false, 'Ruled out because correcting the reversible causes (magnesium, potassium) is essential even if cardioversion or defibrillation is also required for instability.', 4),
('c1000000-0000-0000-0000-000000000011', 'E', 'Observe without treatment as episodes are self-terminating', false, 'Ruled out because torsades carries a risk of degeneration to VF and must be actively treated.', 5),
('c1000000-0000-0000-0000-000000000012', 'A', 'Give intravenous amiodarone as first-line therapy', false, 'Ruled out because amiodarone is reserved for cases refractory to adenosine/vagal manoeuvres or when adenosine is contraindicated.', 1),
('c1000000-0000-0000-0000-000000000012', 'B', 'Perform immediate synchronised cardioversion', false, 'Ruled out because cardioversion is not the first step in a haemodynamically stable patient.', 2),
('c1000000-0000-0000-0000-000000000012', 'C', 'Start an oral beta-blocker and discharge for outpatient follow-up', false, 'Ruled out because acute termination of the tachycardia should be attempted first.', 3),
('c1000000-0000-0000-0000-000000000012', 'D', 'Attempt vagal manoeuvres (e.g. Valsalva manoeuvre or carotid sinus massage), and if unsuccessful give intravenous adenosine', true, 'Correct. Vagal manoeuvres are first-line for stable regular narrow complex tachycardia (SVT), followed by adenosine if unsuccessful.', 4),
('c1000000-0000-0000-0000-000000000012', 'E', 'Give intravenous digoxin as first-line', false, 'Ruled out because digoxin is not first-line for acute termination of SVT.', 5),
('c1000000-0000-0000-0000-000000000013', 'A', 'Sit the patient upright, give high-flow oxygen to correct hypoxia, and administer intravenous furosemide', true, 'Correct. Acute pulmonary oedema is managed with an upright position, oxygen, and IV loop diuretics.', 1),
('c1000000-0000-0000-0000-000000000013', 'B', 'Lie the patient flat and give a large-volume intravenous fluid bolus', false, 'Ruled out because IV fluids would worsen pulmonary congestion and lying flat worsens breathlessness.', 2),
('c1000000-0000-0000-0000-000000000013', 'C', 'Start an oral beta-blocker immediately at full dose', false, 'Ruled out because beta-blockers are not started/uptitrated during acute decompensation; they are introduced once the patient is stable.', 3),
('c1000000-0000-0000-0000-000000000013', 'D', 'Give intravenous adrenaline as first-line', false, 'Ruled out because adrenaline is not indicated unless there is cardiogenic shock or cardiac arrest.', 4),
('c1000000-0000-0000-0000-000000000013', 'E', 'Discharge with an increased dose of oral diuretic if he improves symptomatically over 30 minutes', false, 'Ruled out because this acute severe presentation requires admission with IV treatment and monitoring, not early discharge.', 5),
('c1000000-0000-0000-0000-000000000014', 'A', 'A calcium channel blocker such as verapamil as first-line therapy', false, 'Ruled out because negatively inotropic calcium channel blockers are avoided in HFrEF.', 1),
('c1000000-0000-0000-0000-000000000014', 'B', 'An ACE inhibitor (or ARB if not tolerated) and a beta-blocker licensed for heart failure, titrated up as tolerated', true, 'Correct. First-line disease-modifying therapy for HFrEF is an ACE inhibitor/ARB combined with a beta-blocker licensed for heart failure.', 2),
('c1000000-0000-0000-0000-000000000014', 'C', 'High-dose loop diuretic monotherapy without disease-modifying therapy', false, 'Ruled out because diuretics treat congestive symptoms but do not on their own improve long-term prognosis in HFrEF.', 3),
('c1000000-0000-0000-0000-000000000014', 'D', 'An SGLT2 inhibitor alone, without any other foundational therapy', false, 'Ruled out because SGLT2 inhibitors form part of combination heart failure therapy, not a sole first agent used in isolation.', 4),
('c1000000-0000-0000-0000-000000000014', 'E', 'NSAIDs for symptomatic relief of ankle swelling', false, 'Ruled out because NSAIDs cause fluid retention and can precipitate decompensation in heart failure.', 5),
('c1000000-0000-0000-0000-000000000015', 'A', 'Heart failure with reduced ejection fraction (HFrEF)', false, 'Ruled out because the LVEF is preserved (58%), not reduced.', 1),
('c1000000-0000-0000-0000-000000000015', 'B', 'Constrictive pericarditis', false, 'Ruled out because the echocardiographic findings here (diastolic dysfunction, LA enlargement) fit HFpEF rather than pericardial constriction.', 2),
('c1000000-0000-0000-0000-000000000015', 'C', 'Pulmonary embolism', false, 'Ruled out because this does not explain the chronic pattern with diastolic dysfunction and left atrial enlargement seen on echo.', 3),
('c1000000-0000-0000-0000-000000000015', 'D', 'Nephrotic syndrome', false, 'Ruled out because nephrotic syndrome would show proteinuria/hypoalbuminaemia, not a raised JVP with elevated BNP and diastolic dysfunction.', 4),
('c1000000-0000-0000-0000-000000000015', 'E', 'Heart failure with preserved ejection fraction (HFpEF)', true, 'Correct. Symptoms and signs of heart failure with a preserved LVEF, diastolic dysfunction, and left atrial enlargement are characteristic of HFpEF.', 5),
('c1000000-0000-0000-0000-000000000016', 'A', 'Cardiogenic shock secondary to extensive myocardial infarction', true, 'Correct. Extensive infarction can cause pump failure with hypotension, poor perfusion, pulmonary oedema and end-organ dysfunction.', 1),
('c1000000-0000-0000-0000-000000000016', 'B', 'Hypovolaemic shock due to dehydration', false, 'Ruled out because there is no history of fluid loss, and the clinical picture (pulmonary oedema after a large MI) fits cardiogenic rather than hypovolaemic shock.', 2),
('c1000000-0000-0000-0000-000000000016', 'C', 'Septic shock secondary to hospital-acquired infection', false, 'Ruled out because there is no fever or infective source described, and the timing fits pump failure after a large MI.', 3),
('c1000000-0000-0000-0000-000000000016', 'D', 'Anaphylaxis to a medication given during PCI', false, 'Ruled out because there is no rash, wheeze, or exposure history described, and the pattern fits cardiac pump failure.', 4),
('c1000000-0000-0000-0000-000000000016', 'E', 'Vasovagal syncope', false, 'Ruled out because this does not explain persistent hypotension, tachycardia and pulmonary oedema.', 5),
('c1000000-0000-0000-0000-000000000017', 'A', 'Vasovagal syncope', false, 'Ruled out because the exertional pattern, family history of sudden death, and abnormal murmur/ECG point away from a simple vasovagal cause.', 1),
('c1000000-0000-0000-0000-000000000017', 'B', 'Aortic stenosis', false, 'Ruled out because the AS murmur typically decreases with Valsalva, and this pattern with family history is more consistent with HOCM.', 2),
('c1000000-0000-0000-0000-000000000017', 'C', 'Panic disorder', false, 'Ruled out because this does not explain the murmur, ECG changes, or family history of sudden death.', 3),
('c1000000-0000-0000-0000-000000000017', 'D', 'Hypertrophic cardiomyopathy', true, 'Correct. Exertional syncope, a family history of sudden death, a murmur increasing with reduced preload manoeuvres, and LVH with deep T-wave inversion are classic for HOCM.', 4),
('c1000000-0000-0000-0000-000000000017', 'E', 'Innocent (physiological) murmur', false, 'Ruled out because the exertional syncope and family history are red flags requiring urgent cardiology assessment, not reassurance.', 5),
('c1000000-0000-0000-0000-000000000018', 'A', 'Pulmonary embolism', false, 'Ruled out because the echo findings (dilated LV, reduced EF) point to cardiomyopathy rather than PE, though PE is an important differential for postpartum breathlessness.', 1),
('c1000000-0000-0000-0000-000000000018', 'B', 'Normal physiological postpartum fluid retention', false, 'Ruled out because a reduced ejection fraction and heart failure signs are pathological, not normal.', 2),
('c1000000-0000-0000-0000-000000000018', 'C', 'Postpartum psychosis presenting with somatic symptoms', false, 'Ruled out because objective heart failure signs and echo findings confirm an organic cardiac cause.', 3),
('c1000000-0000-0000-0000-000000000018', 'D', 'Community-acquired pneumonia', false, 'Ruled out because there is no fever or productive cough described, and echo findings confirm cardiomyopathy.', 4),
('c1000000-0000-0000-0000-000000000018', 'E', 'Peripartum cardiomyopathy', true, 'Correct. Heart failure presenting in the last month of pregnancy or in the months following delivery, with a dilated poorly functioning left ventricle, is characteristic of peripartum cardiomyopathy.', 5),
('c1000000-0000-0000-0000-000000000019', 'A', 'Start antihypertensive medication immediately based on this single clinic reading', false, 'Ruled out because a single clinic reading risks overdiagnosis due to the white-coat effect; confirmation is required first.', 1),
('c1000000-0000-0000-0000-000000000019', 'B', 'Offer ambulatory blood pressure monitoring (or home blood pressure monitoring) to confirm the diagnosis before starting treatment', true, 'Correct. A single elevated clinic reading should be confirmed with ABPM/HBPM due to the white-coat effect before diagnosing hypertension.', 2),
('c1000000-0000-0000-0000-000000000019', 'C', 'Reassure him that his blood pressure is normal for his age', false, 'Ruled out because this reading is in the hypertensive range and requires further assessment, not dismissal.', 3),
('c1000000-0000-0000-0000-000000000019', 'D', 'Refer for immediate hospital admission', false, 'Ruled out because this is not a hypertensive emergency; there are no red-flag features.', 4),
('c1000000-0000-0000-0000-000000000019', 'E', 'Arrange renal artery imaging as the first investigation', false, 'Ruled out because this is not indicated as a first step without features suggesting secondary hypertension.', 5),
('c1000000-0000-0000-0000-000000000020', 'A', 'An ACE inhibitor', false, 'Ruled out because ACE inhibitors are first-line for patients under 55 without African/Caribbean family origin, or those with type 2 diabetes, not this patient.', 1),
('c1000000-0000-0000-0000-000000000020', 'B', 'A thiazide-like diuretic as first-line before considering other agents', false, 'Ruled out because thiazide-like diuretics are typically used at a later step, not first-line.', 2),
('c1000000-0000-0000-0000-000000000020', 'C', 'A calcium channel blocker', true, 'Correct. Calcium channel blockers are first-line for patients of Black African or African-Caribbean family origin, regardless of age.', 3),
('c1000000-0000-0000-0000-000000000020', 'D', 'A beta-blocker as first-line', false, 'Ruled out because beta-blockers are not first-line for uncomplicated essential hypertension.', 4),
('c1000000-0000-0000-0000-000000000020', 'E', 'An alpha-blocker as first-line', false, 'Ruled out because alpha-blockers are reserved for resistant hypertension, not first-line therapy.', 5),
('c1000000-0000-0000-0000-000000000021', 'A', 'Admit for controlled, gradual reduction of blood pressure with intravenous antihypertensive therapy under close monitoring', true, 'Correct. Malignant hypertension with papilloedema requires hospital admission and controlled, gradual BP reduction to avoid hypoperfusion.', 1),
('c1000000-0000-0000-0000-000000000021', 'B', 'Rapidly lower blood pressure to normal within the first hour using oral medication at home', false, 'Ruled out because rapid reduction risks cerebral hypoperfusion/stroke; controlled gradual reduction in hospital is required.', 2),
('c1000000-0000-0000-0000-000000000021', 'C', 'Reassure and arrange routine GP follow-up in 2 weeks', false, 'Ruled out because papilloedema and haemorrhages indicate a hypertensive emergency requiring admission, not routine follow-up.', 3),
('c1000000-0000-0000-0000-000000000021', 'D', 'Give a single dose of sublingual nifedipine and discharge if he feels better', false, 'Ruled out because unpredictable, rapid drops in blood pressure are dangerous and this is not appropriate management.', 4),
('c1000000-0000-0000-0000-000000000021', 'E', 'Start oral antihypertensives only, with review by the GP in one week', false, 'Ruled out because target-organ damage requires urgent admission and monitoring, not delayed outpatient review.', 5),
('c1000000-0000-0000-0000-000000000022', 'A', 'Chronic essential hypertension', false, 'Ruled out because new-onset hypertension with proteinuria after 20 weeks indicates pre-eclampsia, not pre-existing chronic hypertension.', 1),
('c1000000-0000-0000-0000-000000000022', 'B', 'Pre-eclampsia', true, 'Correct. New hypertension after 20 weeks gestation with significant proteinuria, and features such as epigastric pain and headache, indicate pre-eclampsia.', 2),
('c1000000-0000-0000-0000-000000000022', 'C', 'Gestational hypertension without proteinuria', false, 'Ruled out because significant proteinuria is present here, distinguishing pre-eclampsia from gestational hypertension alone.', 3),
('c1000000-0000-0000-0000-000000000022', 'D', 'Urinary tract infection', false, 'Ruled out because this does not explain the hypertension, headache, and epigastric pain together.', 4),
('c1000000-0000-0000-0000-000000000022', 'E', 'Normal physiological changes of pregnancy', false, 'Ruled out because these features are pathological and require urgent obstetric assessment.', 5),
('c1000000-0000-0000-0000-000000000023', 'A', 'Add a beta-blocker as the next preferred agent', false, 'Ruled out because a beta-blocker is considered if spironolactone is unsuitable, not as the preferred next step here.', 1),
('c1000000-0000-0000-0000-000000000023', 'B', 'Switch the ACE inhibitor to a second calcium channel blocker', false, 'Ruled out because this is not the recommended stepwise approach for resistant hypertension.', 2),
('c1000000-0000-0000-0000-000000000023', 'C', 'Stop all antihypertensives and refer for lifestyle advice alone', false, 'Ruled out because this is inappropriate given persistently high blood pressure on three agents.', 3),
('c1000000-0000-0000-0000-000000000023', 'D', 'Add low-dose spironolactone, with monitoring of renal function and potassium', true, 'Correct. Spironolactone is the preferred fourth agent in resistant hypertension when potassium is <=4.5 mmol/L.', 4),
('c1000000-0000-0000-0000-000000000023', 'E', 'Add a further thiazide-like diuretic at a higher dose', false, 'Ruled out because he is already on an optimal-dose thiazide-like diuretic; resistant hypertension management moves to a fourth distinct agent.', 5),
('c1000000-0000-0000-0000-000000000024', 'A', 'Essential (primary) hypertension', false, 'Ruled out because the young age, resistant hypertension, renal bruit and ACEi-induced creatinine rise point to a secondary, renovascular cause.', 1),
('c1000000-0000-0000-0000-000000000024', 'B', $x$Conn's syndrome (primary hyperaldosteronism)$x$, false, $x$Ruled out because Conn's syndrome typically presents with hypertension and hypokalaemia, not a renal bruit or ACEi-induced creatinine rise.$x$, 2),
('c1000000-0000-0000-0000-000000000024', 'C', 'Phaeochromocytoma', false, 'Ruled out because phaeochromocytoma classically causes episodic hypertension with palpitations, headache and sweating, not this pattern.', 3),
('c1000000-0000-0000-0000-000000000024', 'D', 'Coarctation of the aorta', false, 'Ruled out because coarctation typically presents with radio-femoral delay and upper-limb hypertension with lower-limb hypotension, not a renal bruit.', 4),
('c1000000-0000-0000-0000-000000000024', 'E', 'Renal artery stenosis (consider fibromuscular dysplasia given her age and sex)', true, 'Correct. Young age, resistant hypertension, a renal bruit, and creatinine rise after starting an ACE inhibitor are classic features of renal artery stenosis.', 5),
('c1000000-0000-0000-0000-000000000025', 'A', 'Community-acquired pneumonia with septic emboli', false, 'Ruled out because the vegetation on echo and murmur point primarily to endocarditis as the source, not pneumonia.', 1),
('c1000000-0000-0000-0000-000000000025', 'B', 'Rheumatic fever', false, 'Ruled out because the clinical context (IVDU, S. aureus bacteraemia, tricuspid vegetation) is classic for IE, not rheumatic heart disease.', 2),
('c1000000-0000-0000-0000-000000000025', 'C', 'Infective endocarditis of the tricuspid valve', true, 'Correct. IV drug use is a major risk factor for right-sided endocarditis, typically caused by Staphylococcus aureus, with a vegetation confirming the diagnosis.', 3),
('c1000000-0000-0000-0000-000000000025', 'D', 'Infective myocarditis', false, 'Ruled out because a vegetation and valvular murmur specifically indicate endocarditis rather than myocarditis.', 4),
('c1000000-0000-0000-0000-000000000025', 'E', 'Deep vein thrombosis with pulmonary embolism', false, 'Ruled out because this does not explain the fever, murmur and vegetation seen on echocardiogram.', 5),
('c1000000-0000-0000-0000-000000000026', 'A', 'Withhold antibiotics entirely until blood culture results are finalised in 5 days', false, 'Ruled out because this delay is unacceptable in suspected endocarditis, a life-threatening infection.', 1),
('c1000000-0000-0000-0000-000000000026', 'B', 'Start a single dose of oral antibiotics and discharge home pending outpatient follow-up', false, 'Ruled out because suspected IE requires admission and IV antibiotic therapy, not oral outpatient treatment.', 2),
('c1000000-0000-0000-0000-000000000026', 'C', 'Give antifungal therapy empirically as first-line', false, 'Ruled out because bacterial causes are far more common; antifungals are not first-line empirically.', 3),
('c1000000-0000-0000-0000-000000000026', 'D', 'Delay blood cultures until after starting antibiotics to avoid delaying treatment', false, 'Ruled out because blood cultures must be taken before antibiotics to maximise organism yield.', 4),
('c1000000-0000-0000-0000-000000000026', 'E', 'Start broad-spectrum intravenous antibiotics per local/national endocarditis guidance after blood cultures have been taken, then tailor once organism and sensitivities are known', true, 'Correct. Empirical broad-spectrum IV antibiotics are started promptly after cultures are taken and later rationalised.', 5),
('c1000000-0000-0000-0000-000000000027', 'A', 'Janeway lesions', false, 'Ruled out because Janeway lesions are non-tender, seen on palms/soles, as described separately for the palmar macules.', 1),
('c1000000-0000-0000-0000-000000000027', 'B', 'Roth spots', false, 'Ruled out because Roth spots are retinal haemorrhages seen on fundoscopy, not skin findings on fingers.', 2),
('c1000000-0000-0000-0000-000000000027', 'C', 'Splinter haemorrhages', false, 'Ruled out because these are already separately described under the nails, distinct from the tender finger-pad nodules.', 3),
('c1000000-0000-0000-0000-000000000027', 'D', $x$Osler's nodes$x$, true, $x$Correct. Osler's nodes are tender, erythematous nodules typically on the finger/toe pads, caused by immune complex deposition.$x$, 4),
('c1000000-0000-0000-0000-000000000027', 'E', 'Erythema nodosum', false, 'Ruled out because erythema nodosum typically affects the shins and is not a classic peripheral stigma of endocarditis on finger pads.', 5),
('c1000000-0000-0000-0000-000000000028', 'A', 'Antibiotics alone for a fixed 2-week course, with no surgical input required', false, 'Ruled out because abscess formation and prosthetic valve involvement require surgical assessment, not antibiotics alone.', 1),
('c1000000-0000-0000-0000-000000000028', 'B', 'Discharge home on oral antibiotics once he is afebrile for 24 hours', false, 'Ruled out because prosthetic valve endocarditis with abscess is high-risk and requires inpatient IV therapy and surgical input.', 2),
('c1000000-0000-0000-0000-000000000028', 'C', 'Urgent discussion with the cardiac surgical team, alongside targeted intravenous antibiotics, given evidence of paravalvular abscess', true, 'Correct. Paravalvular abscess and prosthetic valve involvement are indications for early surgical referral alongside antibiotics.', 3),
('c1000000-0000-0000-0000-000000000028', 'D', 'Immediate valve replacement without any antibiotic therapy', false, 'Ruled out because antibiotics are essential alongside surgical assessment, not instead of it.', 4),
('c1000000-0000-0000-0000-000000000028', 'E', 'Switch to a purely outpatient antibiotic regimen given clinical stability', false, 'Ruled out because complications (abscess, heart failure) make outpatient management unsafe.', 5),
('c1000000-0000-0000-0000-000000000029', 'A', 'Urgent referral for cardiac surgery (valve repair/replacement)', true, 'Correct. Heart failure due to valve dysfunction and uncontrolled infection despite appropriate antibiotics are indications for surgery.', 1),
('c1000000-0000-0000-0000-000000000029', 'B', 'Continue the same antibiotic regimen for a further 6 weeks with no change in management', false, 'Ruled out because ongoing heart failure and persistent bacteraemia despite appropriate antibiotics are indications for surgery, not continuing the same plan unchanged.', 2),
('c1000000-0000-0000-0000-000000000029', 'C', 'Switch to broad-spectrum oral antibiotics', false, 'Ruled out because this is not the appropriate route or step given ongoing severe complications.', 3),
('c1000000-0000-0000-0000-000000000029', 'D', 'Discharge with outpatient antibiotic therapy and cardiology follow-up in 4 weeks', false, 'Ruled out because this is unsafe given ongoing heart failure and bacteraemia.', 4),
('c1000000-0000-0000-0000-000000000029', 'E', 'Add antifungal therapy empirically', false, 'Ruled out because there is no indication of a fungal cause here; switching to antifungal treatment is not appropriate.', 5),
('c1000000-0000-0000-0000-000000000030', 'A', 'He should take a single dose of amoxicillin 1 hour before every dental procedure for life', false, 'Ruled out because routine antibiotic prophylaxis for dental procedures is not recommended by current UK guidance regardless of cardiac risk category.', 1),
('c1000000-0000-0000-0000-000000000030', 'B', 'Routine antibiotic prophylaxis is not recommended for dental procedures, but good oral hygiene should be emphasised', true, 'Correct. Current UK guidance does not recommend routine antibiotic prophylaxis for dental procedures, even in high-risk cardiac patients.', 2),
('c1000000-0000-0000-0000-000000000030', 'C', 'He requires intravenous antibiotics prior to any dental treatment', false, 'Ruled out because prophylaxis of this kind is not recommended for dental procedures.', 3),
('c1000000-0000-0000-0000-000000000030', 'D', 'He should avoid all dental treatment permanently due to his prosthetic valve', false, 'Ruled out because this is unnecessarily restrictive; dental care with good hygiene is still recommended.', 4),
('c1000000-0000-0000-0000-000000000030', 'E', 'Antibiotic prophylaxis is only needed if he has a penicillin allergy', false, 'Ruled out because allergy status does not change the recommendation; prophylaxis is not routinely recommended regardless.', 5),
('c1000000-0000-0000-0000-000000000031', 'A', 'Primary percutaneous coronary intervention', false, 'Ruled out because the ECG changes are diffuse rather than territorial, consistent with pericarditis rather than STEMI, so no reperfusion is indicated.', 1),
('c1000000-0000-0000-0000-000000000031', 'B', 'High-dose corticosteroids as first-line therapy', false, 'Ruled out because corticosteroids are reserved for cases refractory to NSAIDs/colchicine or with contraindications, not first-line.', 2),
('c1000000-0000-0000-0000-000000000031', 'C', 'Broad-spectrum intravenous antibiotics', false, 'Ruled out because viral pericarditis does not require antibiotics and there is no evidence of bacterial infection.', 3),
('c1000000-0000-0000-0000-000000000031', 'D', 'Strict bed rest with no pharmacological treatment', false, 'Ruled out because NSAIDs/colchicine are first-line pharmacological treatment, not withholding therapy.', 4),
('c1000000-0000-0000-0000-000000000031', 'E', 'NSAIDs (e.g. ibuprofen) combined with colchicine', true, 'Correct. First-line treatment of acute pericarditis is NSAIDs combined with colchicine, which also reduces recurrence.', 5),
('c1000000-0000-0000-0000-000000000032', 'A', 'Intravenous furosemide to reduce fluid overload', false, 'Ruled out because diuretics reduce preload and would worsen cardiac output in tamponade, which is dangerous.', 1),
('c1000000-0000-0000-0000-000000000032', 'B', 'Urgent echocardiography to confirm the diagnosis, followed by emergency pericardiocentesis', true, $x$Correct. Beck's triad and pulsus paradoxus suggest tamponade; echo confirmation and emergency pericardiocentesis are required.$x$, 2),
('c1000000-0000-0000-0000-000000000032', 'C', 'Reassurance and routine oncology outpatient follow-up', false, 'Ruled out because tamponade is life-threatening and requires emergency treatment.', 3),
('c1000000-0000-0000-0000-000000000032', 'D', 'High-dose beta-blocker to control heart rate', false, 'Ruled out because this would reduce the compensatory tachycardia needed to maintain cardiac output, which is dangerous.', 4),
('c1000000-0000-0000-0000-000000000032', 'E', 'Anticoagulation for suspected pulmonary embolism', false, $x$Ruled out because the clinical findings (Beck's triad, pulsus paradoxus) point to tamponade, and anticoagulation could worsen a haemorrhagic effusion.$x$, 5),
('c1000000-0000-0000-0000-000000000033', 'A', 'Cardiac tamponade', false, $x$Ruled out because tamponade causes pulsus paradoxus rather than Kussmaul's sign, and typically presents acutely rather than with this chronic pattern.$x$, 1),
('c1000000-0000-0000-0000-000000000033', 'B', 'Right-sided heart failure due to pulmonary hypertension', false, $x$Ruled out because the history of TB and Kussmaul's sign point more specifically to constrictive pericarditis.$x$, 2),
('c1000000-0000-0000-0000-000000000033', 'C', 'Budd-Chiari syndrome', false, $x$Ruled out because this causes hepatic venous outflow obstruction with ascites but does not typically cause a raised JVP or Kussmaul's sign.$x$, 3),
('c1000000-0000-0000-0000-000000000033', 'D', 'Constrictive pericarditis', true, $x$Correct. Pericardial fibrosis (TB is a classic cause) restricts diastolic filling, producing venous congestion and Kussmaul's sign.$x$, 4),
('c1000000-0000-0000-0000-000000000033', 'E', 'Nephrotic syndrome', false, $x$Ruled out because nephrotic syndrome causes oedema/ascites via hypoalbuminaemia, not raised JVP or Kussmaul's sign.$x$, 5),
('c1000000-0000-0000-0000-000000000034', 'A', 'Recurrent myocardial infarction', false, 'Ruled out because the pleuritic pain, friction rub, fever and effusion at this time interval are typical of autoimmune pericarditis rather than re-infarction.', 1),
('c1000000-0000-0000-0000-000000000034', 'B', 'Bacterial pneumonia', false, 'Ruled out because the clinical picture fits pericarditis rather than a primary respiratory infection.', 2),
('c1000000-0000-0000-0000-000000000034', 'C', $x$Dressler's syndrome (post-myocardial infarction pericarditis)$x$, true, $x$Correct. Dressler's syndrome is an autoimmune pericarditis occurring weeks after MI, with pleuritic pain, fever, and a friction rub/effusion.$x$, 3),
('c1000000-0000-0000-0000-000000000034', 'D', 'Pulmonary embolism', false, 'Ruled out because this does not explain the friction rub and pericardial effusion, though it is an important differential for pleuritic chest pain.', 4),
('c1000000-0000-0000-0000-000000000034', 'E', 'Aortic dissection', false, 'Ruled out because dissection typically causes sudden tearing pain with haemodynamic compromise, not this subacute febrile illness.', 5),
('c1000000-0000-0000-0000-000000000035', 'A', 'Widespread (non-territorial) concave ST elevation with PR depression and no reciprocal ST depression', true, 'Correct. This diffuse pattern without reciprocal changes is characteristic of pericarditis rather than a single-territory STEMI.', 1),
('c1000000-0000-0000-0000-000000000035', 'B', 'ST elevation confined to a single coronary territory with reciprocal depression in opposing leads', false, 'Ruled out because this pattern is typical of STEMI, not pericarditis.', 2),
('c1000000-0000-0000-0000-000000000035', 'C', 'New left bundle branch block', false, 'Ruled out because this is not a discriminating feature described here and is more associated with concern for ischaemia.', 3),
('c1000000-0000-0000-0000-000000000035', 'D', 'Pathological Q waves', false, 'Ruled out because these suggest previous/established infarction, not a feature used to diagnose pericarditis.', 4),
('c1000000-0000-0000-0000-000000000035', 'E', 'Prolonged QT interval', false, 'Ruled out because this is not a feature of pericarditis and is relevant to arrhythmia risk instead.', 5),
('c1000000-0000-0000-0000-000000000036', 'A', 'Immediate pericardiocentesis regardless of haemodynamic stability', false, 'Ruled out because this is not required in a stable patient without tamponade.', 1),
('c1000000-0000-0000-0000-000000000036', 'B', 'High-dose intravenous corticosteroids as first-line therapy', false, 'Ruled out because this is not indicated for hypothyroid-related effusion; the underlying endocrine cause should be treated.', 2),
('c1000000-0000-0000-0000-000000000036', 'C', 'Treat the underlying cause (start thyroid hormone replacement) with close monitoring for signs of tamponade, reserving pericardiocentesis for haemodynamic compromise', true, 'Correct. Hypothyroid-related effusions often improve with thyroid hormone replacement; pericardiocentesis is reserved for tamponade.', 3),
('c1000000-0000-0000-0000-000000000036', 'D', 'Urgent cardiac surgery for pericardial window', false, 'Ruled out because surgery is reserved for recurrent/refractory effusions, not first-line here.', 4),
('c1000000-0000-0000-0000-000000000036', 'E', 'Discharge with no follow-up, as she is currently stable', false, 'Ruled out because monitoring is needed given the large effusion and risk of progression to tamponade.', 5),
('c1000000-0000-0000-0000-000000000037', 'A', 'Mitral regurgitation', false, 'Ruled out because MR produces a pansystolic murmur at the apex radiating to the axilla, not an ejection systolic murmur with a slow-rising pulse.', 1),
('c1000000-0000-0000-0000-000000000037', 'B', 'Hypertrophic obstructive cardiomyopathy', false, 'Ruled out because the murmur in HOCM typically increases with Valsalva/standing rather than expiration, and the pulse character differs.', 2),
('c1000000-0000-0000-0000-000000000037', 'C', 'Pulmonary stenosis', false, 'Ruled out because pulmonary stenosis is loudest at the pulmonary area radiating to the back, not to the carotids.', 3),
('c1000000-0000-0000-0000-000000000037', 'D', 'Aortic stenosis', true, 'Correct. Exertional syncope with a slow-rising pulse and an ejection systolic murmur radiating to the carotids is classic for aortic stenosis.', 4),
('c1000000-0000-0000-0000-000000000037', 'E', 'Aortic sclerosis', false, 'Ruled out because sclerosis represents valve thickening without significant obstruction and would not typically cause exertional syncope or a slow-rising pulse.', 5),
('c1000000-0000-0000-0000-000000000038', 'A', 'Aortic stenosis', false, 'Ruled out because AS produces an ejection systolic murmur radiating to the carotids, not a pansystolic murmur at the apex radiating to the axilla.', 1),
('c1000000-0000-0000-0000-000000000038', 'B', 'Mitral regurgitation', true, 'Correct. A pansystolic murmur loudest at the apex radiating to the axilla, with a displaced apex beat, is classic for mitral regurgitation.', 2),
('c1000000-0000-0000-0000-000000000038', 'C', 'Tricuspid regurgitation', false, $x$Ruled out because TR is loudest at the left lower sternal edge, associated with a raised JVP with giant 'v' waves, not apex/axilla radiation.$x$, 3),
('c1000000-0000-0000-0000-000000000038', 'D', 'Ventricular septal defect', false, 'Ruled out because a VSD murmur is loudest at the left sternal edge and typically presents from childhood unless acquired acutely post-MI.', 4),
('c1000000-0000-0000-0000-000000000038', 'E', 'Atrial septal defect', false, 'Ruled out because ASD produces an ejection systolic murmur at the pulmonary area with fixed splitting of the second heart sound.', 5),
('c1000000-0000-0000-0000-000000000039', 'A', 'Rheumatic heart disease following childhood streptococcal infection', true, 'Correct. Rheumatic heart disease from untreated childhood streptococcal pharyngitis remains the most common cause of mitral stenosis worldwide.', 1),
('c1000000-0000-0000-0000-000000000039', 'B', 'Infective endocarditis', false, 'Ruled out because endocarditis typically presents acutely with fever and regurgitant lesions rather than this chronic stenotic picture.', 2),
('c1000000-0000-0000-0000-000000000039', 'C', 'Congenital bicuspid aortic valve', false, 'Ruled out because this relates to the aortic valve, not the mitral valve, and does not explain this murmur.', 3),
('c1000000-0000-0000-0000-000000000039', 'D', 'Age-related degenerative calcification', false, 'Ruled out because this is more typical of aortic stenosis in older patients and does not fit the history of childhood sore throats.', 4),
('c1000000-0000-0000-0000-000000000039', 'E', 'Marfan syndrome', false, 'Ruled out because Marfan syndrome is associated with aortic root dilatation and mitral valve prolapse, not classic mitral stenosis with this history.', 5),
('c1000000-0000-0000-0000-000000000040', 'A', 'Aortic stenosis', false, 'Ruled out because AS causes a slow-rising pulse and narrow pulse pressure with an ejection systolic (not diastolic) murmur.', 1),
('c1000000-0000-0000-0000-000000000040', 'B', 'Mitral stenosis', false, 'Ruled out because mitral stenosis causes a mid-diastolic murmur at the apex, not an early diastolic murmur at the left sternal edge, and does not cause a collapsing pulse.', 2),
('c1000000-0000-0000-0000-000000000040', 'C', 'Patent ductus arteriosus', false, 'Ruled out because PDA classically produces a continuous machinery murmur, not an isolated early diastolic murmur.', 3),
('c1000000-0000-0000-0000-000000000040', 'D', 'Tricuspid stenosis', false, 'Ruled out because this is rare and causes a diastolic murmur at the lower left sternal edge with signs of right heart congestion, not a collapsing pulse.', 4),
('c1000000-0000-0000-0000-000000000040', 'E', 'Aortic regurgitation', true, 'Correct. A collapsing pulse, wide pulse pressure, and early diastolic murmur at the left sternal edge are classic for aortic regurgitation.', 5),
('c1000000-0000-0000-0000-000000000041', 'A', 'Manage conservatively with diuretics and afterload reduction alone, deferring surgery', false, 'Ruled out because acute severe AR with heart failure usually needs emergency surgery, not medical management alone.', 1),
('c1000000-0000-0000-0000-000000000041', 'B', 'Intra-aortic balloon pump insertion as definitive treatment', false, 'Ruled out because a balloon pump is contraindicated in aortic regurgitation as it worsens regurgitant flow.', 2),
('c1000000-0000-0000-0000-000000000041', 'C', 'Urgent referral for emergency aortic valve surgery, in addition to continuing targeted antibiotics', true, 'Correct. Acute severe AR with heart failure is poorly tolerated and requires emergency surgery alongside antibiotics.', 3),
('c1000000-0000-0000-0000-000000000041', 'D', 'Wait until a full 6-week course of antibiotics is completed before considering surgery', false, 'Ruled out because acute decompensation from severe AR is an indication for emergency surgery, not delay.', 4),
('c1000000-0000-0000-0000-000000000041', 'E', 'Reassure and discharge once his heart rate settles', false, 'Ruled out because this is unsafe in acute severe AR with heart failure signs.', 5),
('c1000000-0000-0000-0000-000000000042', 'A', 'Immediate aortic valve replacement, as bicuspid valves always require early surgery', false, 'Ruled out because surgery is not indicated for mild stenosis without severe symptoms/dimensions; surveillance is appropriate.', 1),
('c1000000-0000-0000-0000-000000000042', 'B', 'Regular surveillance imaging (echocardiography and/or MRI) to monitor valve function and aortic root diameter over time', true, 'Correct. Bicuspid aortic valve requires ongoing surveillance of valve function and aortic dimensions given the risk of progressive dysfunction and dissection.', 2),
('c1000000-0000-0000-0000-000000000042', 'C', 'No further follow-up is needed as he is currently asymptomatic', false, 'Ruled out because the risk of progressive valve dysfunction and aortic dilatation/dissection means ongoing surveillance is essential.', 3),
('c1000000-0000-0000-0000-000000000042', 'D', 'Start long-term prophylactic antibiotics to prevent endocarditis', false, 'Ruled out because this is not routinely recommended for this indication.', 4),
('c1000000-0000-0000-0000-000000000042', 'E', 'Advise unrestricted high-intensity competitive sport with no further assessment', false, 'Ruled out because activity guidance and follow-up assessment are required rather than no further action.', 5),
('c1000000-0000-0000-0000-000000000043', 'A', 'Normal respiratory variation in venous return causing physiological splitting', false, 'Ruled out because physiological splitting varies with respiration; the splitting described here is fixed and does not change.', 1),
('c1000000-0000-0000-0000-000000000043', 'B', 'Left bundle branch block causing delayed left ventricular activation', false, 'Ruled out because this would cause a different pattern of splitting, not the fixed splitting characteristic of ASD.', 2),
('c1000000-0000-0000-0000-000000000043', 'C', 'Severe pulmonary hypertension causing a loud single second heart sound', false, 'Ruled out because a loud single S2 is different from fixed splitting and does not explain this mechanism.', 3),
('c1000000-0000-0000-0000-000000000043', 'D', 'Aortic stenosis causing delayed aortic valve closure', false, 'Ruled out because this affects a different valve and does not explain the mechanism of fixed splitting in ASD.', 4),
('c1000000-0000-0000-0000-000000000043', 'E', 'Delayed closure of the pulmonary valve due to increased right-sided flow through the atrial septal defect, which does not vary with respiration', true, 'Correct. Increased right heart flow from the shunt delays pulmonary valve closure, and because both atria communicate, this splitting does not vary with respiration.', 5),
('c1000000-0000-0000-0000-000000000044', 'A', 'Urgent referral for emergency cardiothoracic surgery, alongside blood pressure and heart rate control', true, 'Correct. Type A aortic dissection involving the ascending aorta is a surgical emergency requiring urgent cardiothoracic surgery.', 1),
('c1000000-0000-0000-0000-000000000044', 'B', 'Thrombolysis to treat the suspected dissection', false, 'Ruled out because thrombolysis is contraindicated in aortic dissection as it would worsen bleeding.', 2),
('c1000000-0000-0000-0000-000000000044', 'C', 'Discharge with outpatient vascular surgery follow-up', false, 'Ruled out because Type A dissection is a surgical emergency, not something managed as an outpatient.', 3),
('c1000000-0000-0000-0000-000000000044', 'D', 'Manage conservatively with blood pressure control alone, without surgical referral', false, 'Ruled out because ascending (Type A) dissections require emergency surgery due to high risk of rupture and death; medical management alone is for Type B.', 4),
('c1000000-0000-0000-0000-000000000044', 'E', 'Insert an intra-aortic balloon pump as definitive treatment', false, 'Ruled out because this is not appropriate or definitive management for aortic dissection.', 5),
('c1000000-0000-0000-0000-000000000045', 'A', 'Emergency open surgical repair as first-line for all descending dissections', false, 'Ruled out because uncomplicated Type B dissection is managed medically initially, with intervention reserved for complications.', 1),
('c1000000-0000-0000-0000-000000000045', 'B', 'Thrombolysis to dissolve the dissection flap', false, 'Ruled out because thrombolysis is contraindicated in aortic dissection.', 2),
('c1000000-0000-0000-0000-000000000045', 'C', 'Discharge home with oral antihypertensives and GP follow-up in a week', false, 'Ruled out because close inpatient monitoring is required initially given the risk of progression or complication.', 3),
('c1000000-0000-0000-0000-000000000045', 'D', 'Medical management with intravenous antihypertensive/rate-control therapy to reduce blood pressure and shear stress, with close monitoring', true, 'Correct. Uncomplicated Type B dissection is managed medically first-line with tight blood pressure and heart rate control.', 4),
('c1000000-0000-0000-0000-000000000045', 'E', 'Immediate pericardiocentesis', false, 'Ruled out because there is no evidence of tamponade; this is a descending, uncomplicated dissection.', 5),
('c1000000-0000-0000-0000-000000000046', 'A', 'Arrange an outpatient CT scan to confirm the diagnosis before any intervention', false, 'Ruled out because this clinical picture demands immediate action, not deferred outpatient imaging.', 1),
('c1000000-0000-0000-0000-000000000046', 'B', 'Give a large-volume rapid crystalloid infusion to normalise blood pressure fully before surgery', false, 'Ruled out because aggressive fluid resuscitation to a fully normal blood pressure can worsen bleeding; permissive hypotension is preferred.', 2),
('c1000000-0000-0000-0000-000000000046', 'C', 'Urgent activation of the vascular surgery emergency pathway for immediate theatre, with permissive hypotension and cautious fluid resuscitation en route', true, 'Correct. Ruptured AAA is a surgical emergency requiring immediate transfer to theatre, with permissive hypotension to avoid worsening haemorrhage.', 3),
('c1000000-0000-0000-0000-000000000046', 'D', 'Discharge with analgesia and GP follow-up', false, 'Ruled out because a ruptured AAA is immediately life-threatening.', 4),
('c1000000-0000-0000-0000-000000000046', 'E', 'Start therapeutic anticoagulation for suspected concurrent venous thromboembolism', false, 'Ruled out because anticoagulation would worsen haemorrhage in a ruptured aneurysm.', 5),
('c1000000-0000-0000-0000-000000000047', 'A', 'Elevate the leg and apply a compression bandage, then review in clinic in 48 hours', false, 'Ruled out because delay risks irreversible limb loss in acute ischaemia.', 1),
('c1000000-0000-0000-0000-000000000047', 'B', 'Urgent vascular surgery referral for emergency revascularisation, with immediate intravenous unfractionated heparin while arrangements are made', true, 'Correct. Acute limb ischaemia requires immediate heparin and urgent vascular surgical assessment for revascularisation.', 2),
('c1000000-0000-0000-0000-000000000047', 'C', 'Start a course of oral antibiotics for suspected cellulitis', false, 'Ruled out because the clinical features (pale, cold, pulseless, painful) indicate ischaemia, not infection.', 3),
('c1000000-0000-0000-0000-000000000047', 'D', 'Arrange elective duplex ultrasound in the outpatient vascular clinic', false, 'Ruled out because this is an emergency requiring immediate action, not elective outpatient assessment.', 4),
('c1000000-0000-0000-0000-000000000047', 'E', 'Apply a warm compress and reassess in the morning', false, 'Ruled out because this delays urgent revascularisation and risks limb loss.', 5),
('c1000000-0000-0000-0000-000000000048', 'A', 'Start prophylactic-dose low molecular weight heparin only', false, 'Ruled out because prophylactic dosing is insufficient for a life-threatening massive PE with shock; therapeutic treatment is needed.', 1),
('c1000000-0000-0000-0000-000000000048', 'B', 'Arrange an outpatient CT pulmonary angiogram within 24 hours', false, 'Ruled out because this is an unsafe delay in a haemodynamically unstable patient.', 2),
('c1000000-0000-0000-0000-000000000048', 'C', 'Insert a permanent IVC filter as definitive treatment', false, 'Ruled out because this is not first-line or definitive treatment for massive PE.', 3),
('c1000000-0000-0000-0000-000000000048', 'D', 'Give high-dose oral aspirin as sole treatment', false, 'Ruled out because this is inadequate for a confirmed massive PE with cardiovascular compromise.', 4),
('c1000000-0000-0000-0000-000000000048', 'E', 'Immediate resuscitation and systemic thrombolysis, given haemodynamic instability consistent with massive (high-risk) pulmonary embolism', true, 'Correct. Massive PE with haemodynamic instability warrants systemic thrombolysis in the absence of contraindications.', 5),
('c1000000-0000-0000-0000-000000000049', 'A', 'Give synchronised cardioversion', false, 'Ruled out because synchronisation is not possible or appropriate in VF as there is no organised QRS to synchronise to.', 1),
('c1000000-0000-0000-0000-000000000049', 'B', 'Give intravenous adenosine immediately', false, 'Ruled out because adenosine is not part of the cardiac arrest algorithm for VF/pulseless VT.', 2),
('c1000000-0000-0000-0000-000000000049', 'C', 'Withhold defibrillation until IV access is secured and adrenaline is given', false, 'Ruled out because defibrillation should not be delayed for drug administration in a shockable rhythm.', 3),
('c1000000-0000-0000-0000-000000000049', 'D', 'Continue high-quality CPR and deliver an immediate unsynchronised defibrillation shock as soon as the rhythm is confirmed as ventricular fibrillation', true, 'Correct. VF is a shockable rhythm; immediate CPR and rapid unsynchronised defibrillation are the priorities in cardiac arrest.', 4),
('c1000000-0000-0000-0000-000000000049', 'E', 'Perform vagal manoeuvres', false, 'Ruled out because vagal manoeuvres are irrelevant and inappropriate in cardiac arrest with a shockable rhythm.', 5),
('c1000000-0000-0000-0000-000000000050', 'A', 'Urgent transfer for coronary angiography given the ST-elevation pattern, alongside post-resuscitation critical care (airway protection, ventilation, targeted temperature management)', true, 'Correct. ST elevation post-arrest should prompt urgent angiography, alongside standard post-resuscitation critical care.', 1),
('c1000000-0000-0000-0000-000000000050', 'B', 'Discharge planning can begin once he is haemodynamically stable, as the arrest has already been successfully treated', false, 'Ruled out because ongoing critical illness requires intensive post-resuscitation care and investigation of the underlying cause, not discharge planning.', 2),
('c1000000-0000-0000-0000-000000000050', 'C', 'Withhold coronary angiography as he is unconscious and cannot consent', false, $x$Ruled out because urgent angiography is still indicated in unconscious patients with ST elevation post-arrest; decisions are made in the patient's best interests.$x$, 3),
('c1000000-0000-0000-0000-000000000050', 'D', 'Active rewarming to achieve hyperthermia to improve neurological outcome', false, 'Ruled out because the evidence-based approach is targeted temperature management avoiding hyperthermia, not deliberately inducing it.', 4),
('c1000000-0000-0000-0000-000000000050', 'E', 'No further investigation is needed as the cause of arrest is already known to be primary VF', false, 'Ruled out because the ST elevation strongly suggests an underlying acute coronary event requiring urgent angiography to identify and treat the culprit lesion.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('c1000000-0000-0000-0000-000000000001', 'ST elevation in V1-V4 indicates an anterior STEMI from LAD occlusion, associated with a larger myocardial territory and higher risk of complications such as cardiogenic shock.', 1),
('c1000000-0000-0000-0000-000000000001', 'Primary PCI within 120 minutes of first medical contact is preferred over thrombolysis; fibrinolysis is considered only when timely PCI cannot be delivered.', 2),
('c1000000-0000-0000-0000-000000000001', 'Oxygen should be titrated to target saturation 94-98%; routine high-flow oxygen in a normoxic ACS patient is not recommended and delays reperfusion.', 3),
('c1000000-0000-0000-0000-000000000002', 'NSTEMI is diagnosed by a troponin rise with ischaemic ECG changes (or a normal ECG) without persistent ST elevation; management is antiplatelet/anticoagulant therapy plus risk-stratified angiography, not thrombolysis.', 1),
('c1000000-0000-0000-0000-000000000002', 'The GRACE score estimates in-hospital and 6-month mortality risk and is used to decide whether angiography should be immediate, within 72 hours, or guided by ongoing risk.', 2),
('c1000000-0000-0000-0000-000000000002', 'Renal impairment requires dose adjustment of anticoagulants (e.g. reduced-dose fondaparinux or LMWH) rather than withholding treatment, as untreated ACS carries substantial risk.', 3),
('c1000000-0000-0000-0000-000000000003', 'A single normal troponin taken shortly after symptom onset does not exclude myocardial infarction; serial troponin testing is required to safely rule out MI.', 1),
('c1000000-0000-0000-0000-000000000003', 'Clinical risk assessment alongside serial troponins determines whether a patient can be safely discharged or needs further investigation.', 2),
('c1000000-0000-0000-0000-000000000003', 'A normal resting ECG does not exclude ACS, particularly soon after resolution of symptoms.', 3),
('c1000000-0000-0000-0000-000000000004', 'Right ventricular infarction complicates inferior STEMI (right coronary artery occlusion) and should be suspected when hypotension develops, especially after nitrates.', 1),
('c1000000-0000-0000-0000-000000000004', 'The right ventricle in this setting is preload-dependent; nitrates, diuretics and other preload-reducing drugs can cause profound hypotension and must be avoided.', 2),
('c1000000-0000-0000-0000-000000000004', 'Management is IV fluid loading to maintain right ventricular filling, alongside standard STEMI reperfusion therapy.', 3),
('c1000000-0000-0000-0000-000000000005', 'Papillary muscle rupture typically occurs 2-7 days post-MI (especially inferior MI affecting the posteromedial papillary muscle) and presents with acute pulmonary oedema and a new apical pansystolic murmur radiating to the axilla.', 1),
('c1000000-0000-0000-0000-000000000005', 'Ventricular septal rupture produces a harsh pansystolic murmur at the left sternal edge, often with a thrill; echocardiography distinguishes the mechanical complications of MI.', 2),
('c1000000-0000-0000-0000-000000000005', 'Mechanical complications of MI require urgent echocardiography and emergency surgical referral.', 3),
('c1000000-0000-0000-0000-000000000006', 'Beta-blockers are avoided in cocaine-associated chest pain because unopposed alpha-adrenergic stimulation can worsen coronary vasospasm and hypertension.', 1),
('c1000000-0000-0000-0000-000000000006', 'Benzodiazepines reduce the sympathetic overdrive (tachycardia, hypertension, agitation) associated with cocaine toxicity and can be used alongside standard ACS therapy.', 2),
('c1000000-0000-0000-0000-000000000006', 'Cocaine-associated STEMI is still managed with aspirin, nitrates and primary PCI when indicated; the key modification is avoiding beta-blockers.', 3),
('c1000000-0000-0000-0000-000000000007', 'Rate control (beta-blocker or rate-limiting calcium channel blocker) is first-line for most patients with AF; digoxin is generally reserved for those who are sedentary or have heart failure.', 1),
('c1000000-0000-0000-0000-000000000007', 'Anticoagulation decisions are based on a validated stroke risk score (CHA2DS2-VASc) rather than the duration of AF alone, since onset is often uncertain and risk persists regardless.', 2),
('c1000000-0000-0000-0000-000000000007', 'Emergency cardioversion is reserved for haemodynamically unstable AF, not stable patients.', 3),
('c1000000-0000-0000-0000-000000000008', 'Adverse features (shock, syncope, myocardial ischaemia, severe heart failure) in a tachyarrhythmia mandate emergency synchronised DC cardioversion regardless of the specific arrhythmia.', 1),
('c1000000-0000-0000-0000-000000000008', 'Synchronised cardioversion (timed to the R wave) is used for organised tachyarrhythmias like AF, distinct from unsynchronised defibrillation used in VF/pulseless VT.', 2),
('c1000000-0000-0000-0000-000000000008', 'Rate-control drugs and elective anticoagulation strategies are inappropriate when a patient is haemodynamically unstable and needs immediate rhythm correction.', 3),
('c1000000-0000-0000-0000-000000000009', 'In a broad complex tachycardia, especially with a history of structural heart disease (e.g. prior MI), ventricular tachycardia should be assumed until proven otherwise.', 1),
('c1000000-0000-0000-0000-000000000009', 'Verapamil and other calcium channel blockers are contraindicated in VT as they can precipitate haemodynamic collapse.', 2),
('c1000000-0000-0000-0000-000000000009', 'Adenosine may be considered only if a regular broad complex tachycardia is confidently thought to be SVT with bundle branch block, but is avoided when VT cannot be excluded.', 3),
('c1000000-0000-0000-0000-000000000010', 'Complete heart block complicating inferior MI (right coronary artery territory, affecting AV nodal blood supply) is often transient but requires immediate treatment if there is haemodynamic compromise.', 1),
('c1000000-0000-0000-0000-000000000010', 'First-line treatment of symptomatic bradycardia is atropine; if there is an inadequate response, transcutaneous pacing (bridging to transvenous pacing) is required.', 2),
('c1000000-0000-0000-0000-000000000010', 'Beta-blockers and other negatively chronotropic drugs should be avoided in bradyarrhythmias.', 3),
('c1000000-0000-0000-0000-000000000011', 'Torsades de pointes is a polymorphic VT associated with QT prolongation; common causes include QT-prolonging drugs (e.g. citalopram, macrolides) and electrolyte disturbance (low potassium, magnesium).', 1),
('c1000000-0000-0000-0000-000000000011', 'First-line treatment is IV magnesium sulfate, with correction of hypokalaemia, and stopping the offending drug(s).', 2),
('c1000000-0000-0000-0000-000000000011', 'Amiodarone (and other QT-prolonging antiarrhythmics) should be avoided as they can worsen torsades; if the patient becomes unstable/pulseless, defibrillation is required.', 3),
('c1000000-0000-0000-0000-000000000012', 'Regular narrow complex tachycardia in a haemodynamically stable patient is most likely SVT (commonly AVNRT); first-line management is vagal manoeuvres.', 1),
('c1000000-0000-0000-0000-000000000012', 'If vagal manoeuvres fail, IV adenosine is given as a rapid bolus with a saline flush, warning the patient of a brief unpleasant sensation.', 2),
('c1000000-0000-0000-0000-000000000012', 'Synchronised cardioversion is reserved for SVT with adverse features/haemodynamic instability, not as first-line in a stable patient.', 3),
('c1000000-0000-0000-0000-000000000013', 'Acute pulmonary oedema is managed with an upright position, oxygen (titrated to saturation), and IV loop diuretics; nitrates may be added if blood pressure allows.', 1),
('c1000000-0000-0000-0000-000000000013', 'IV fluids are avoided as they will worsen pulmonary congestion.', 2),
('c1000000-0000-0000-0000-000000000013', 'Beta-blockers are not started or increased during acute decompensation but are important for chronic HFrEF once the patient is stable and euvolaemic.', 3),
('c1000000-0000-0000-0000-000000000014', 'First-line disease-modifying therapy for HFrEF includes an ACE inhibitor (or ARB) and a beta-blocker licensed for heart failure, started at low dose and titrated up as tolerated.', 1),
('c1000000-0000-0000-0000-000000000014', 'Diuretics manage congestive symptoms but do not on their own improve long-term prognosis in HFrEF.', 2),
('c1000000-0000-0000-0000-000000000014', 'NSAIDs should be avoided in heart failure as they promote sodium and fluid retention and can precipitate decompensation.', 3),
('c1000000-0000-0000-0000-000000000015', 'HFpEF is characterised by symptoms and signs of heart failure with a preserved LVEF (typically >=50%), diastolic dysfunction, and often left atrial enlargement on echocardiography.', 1),
('c1000000-0000-0000-0000-000000000015', 'Risk factors for HFpEF include hypertension, atrial fibrillation, obesity, and older age.', 2),
('c1000000-0000-0000-0000-000000000015', 'Management focuses on treating comorbidities (e.g. hypertension, AF) and congestion (diuretics), as fewer therapies have proven mortality benefit compared with HFrEF.', 3),
('c1000000-0000-0000-0000-000000000016', 'Cardiogenic shock is a recognised complication of large myocardial infarctions and presents with hypotension, poor peripheral perfusion, pulmonary oedema and end-organ dysfunction (confusion, oliguria).', 1),
('c1000000-0000-0000-0000-000000000016', 'Management requires urgent senior/critical care involvement, inotropic support, and consideration of mechanical circulatory support in specialist centres.', 2),
('c1000000-0000-0000-0000-000000000016', 'Distinguishing cardiogenic from hypovolaemic or septic shock relies on the clinical context (recent large MI, pulmonary congestion) rather than any single sign.', 3),
('c1000000-0000-0000-0000-000000000017', 'Hypertrophic cardiomyopathy should be suspected in young patients with exertional syncope/collapse, a family history of sudden cardiac death, and a murmur that increases with manoeuvres reducing preload (e.g. Valsalva, standing).', 1),
('c1000000-0000-0000-0000-000000000017', 'ECG typically shows left ventricular hypertrophy with deep T-wave inversion; echocardiography confirms asymmetric septal hypertrophy.', 2),
('c1000000-0000-0000-0000-000000000017', 'Patients require specialist cardiology referral, activity restriction advice, and screening of first-degree relatives.', 3),
('c1000000-0000-0000-0000-000000000018', 'Peripartum cardiomyopathy typically presents with heart failure symptoms in the last month of pregnancy or within months after delivery, with a dilated, poorly functioning left ventricle.', 1),
('c1000000-0000-0000-0000-000000000018', 'It should be considered in any postpartum woman with unexplained breathlessness, as symptoms can be mistaken for normal postpartum recovery.', 2),
('c1000000-0000-0000-0000-000000000018', 'Management follows standard heart failure principles (with certain drug modifications in pregnancy/breastfeeding) and requires specialist cardiology and obstetric input.', 3),
('c1000000-0000-0000-0000-000000000019', 'A single elevated clinic blood pressure reading should be confirmed with ambulatory (or home) blood pressure monitoring before diagnosing hypertension and starting treatment, due to the white-coat effect.', 1),
('c1000000-0000-0000-0000-000000000019', 'Assessment for end-organ damage and cardiovascular risk factors accompanies the diagnostic work-up.', 2),
('c1000000-0000-0000-0000-000000000019', 'Same-day hospital referral is reserved for severe hypertension with red-flag features (e.g. papilloedema, life-threatening symptoms).', 3),
('c1000000-0000-0000-0000-000000000020', 'First-line antihypertensive choice is guided by age and ethnicity: calcium channel blockers are first-line for patients of Black African or African-Caribbean family origin (of any age) and for patients aged 55 or over without diabetes.', 1),
('c1000000-0000-0000-0000-000000000020', 'ACE inhibitors (or ARBs) are first-line for patients under 55 without African/Caribbean family origin, and for patients with type 2 diabetes of any age/ethnicity.', 2),
('c1000000-0000-0000-0000-000000000020', 'Beta-blockers and alpha-blockers are not first-line for uncomplicated essential hypertension but may be used at later steps or for specific indications.', 3),
('c1000000-0000-0000-0000-000000000021', 'Malignant (accelerated) hypertension with papilloedema and/or retinal haemorrhages indicates a hypertensive emergency and requires hospital admission.', 1),
('c1000000-0000-0000-0000-000000000021', 'Blood pressure should be lowered in a controlled, gradual manner rather than rapidly, as sudden drops risk cerebral or myocardial hypoperfusion.', 2),
('c1000000-0000-0000-0000-000000000021', 'Same-day specialist assessment is required whenever hypertension is accompanied by signs of target-organ damage.', 3),
('c1000000-0000-0000-0000-000000000022', 'Pre-eclampsia is defined as new hypertension after 20 weeks gestation with significant proteinuria (or other evidence of maternal organ dysfunction); epigastric pain and headache can indicate severe disease.', 1),
('c1000000-0000-0000-0000-000000000022', 'It requires urgent obstetric assessment, blood pressure control, and monitoring for progression to eclampsia or HELLP syndrome.', 2),
('c1000000-0000-0000-0000-000000000022', 'Gestational hypertension (without proteinuria/organ dysfunction) is a distinct, generally lower-risk diagnosis, but all new hypertension in pregnancy needs prompt assessment.', 3),
('c1000000-0000-0000-0000-000000000023', 'Resistant hypertension (uncontrolled on three antihypertensives including a diuretic) warrants a fourth agent: spironolactone is preferred if serum potassium is <=4.5 mmol/L.', 1),
('c1000000-0000-0000-0000-000000000023', 'If potassium is >4.5 mmol/L, or spironolactone is contraindicated/not tolerated, an alpha-blocker or beta-blocker is used instead.', 2),
('c1000000-0000-0000-0000-000000000023', 'Confirming adherence and excluding secondary causes of hypertension are important before escalating therapy.', 3),
('c1000000-0000-0000-0000-000000000024', 'Young age at onset, resistant hypertension, a renal artery bruit, and a significant rise in creatinine after starting an ACE inhibitor/ARB are classic features suggesting renal artery stenosis.', 1),
('c1000000-0000-0000-0000-000000000024', 'Fibromuscular dysplasia is an important cause of renal artery stenosis in younger women, whereas atherosclerotic renal artery stenosis is more common in older patients with vascular risk factors.', 2),
('c1000000-0000-0000-0000-000000000024', 'ACE inhibitors/ARBs can precipitate acute kidney injury in bilateral renal artery stenosis (or stenosis of a single functioning kidney) by reducing glomerular filtration pressure.', 3),
('c1000000-0000-0000-0000-000000000025', 'Intravenous drug use is a major risk factor for right-sided (tricuspid valve) infective endocarditis, most commonly caused by Staphylococcus aureus.', 1),
('c1000000-0000-0000-0000-000000000025', 'Diagnosis relies on the modified Duke criteria, combining clinical features, blood cultures, and echocardiographic findings (vegetation, abscess, new valvular regurgitation).', 2),
('c1000000-0000-0000-0000-000000000025', 'Right-sided endocarditis can present with septic pulmonary emboli in addition to systemic features of infection.', 3),
('c1000000-0000-0000-0000-000000000026', 'In suspected infective endocarditis, blood cultures (typically three sets from separate venepuncture sites) should be taken before starting antibiotics, but treatment should not be delayed once cultures are obtained.', 1),
('c1000000-0000-0000-0000-000000000026', 'Empirical broad-spectrum IV antibiotic therapy is started promptly and later rationalised according to the causative organism and sensitivities.', 2),
('c1000000-0000-0000-0000-000000000026', 'Native valve endocarditis is most commonly caused by streptococci and staphylococci; the specific regimen depends on local guidelines and clinical risk factors.', 3),
('c1000000-0000-0000-0000-000000000027', $x$Osler's nodes are tender, erythematous nodules typically on the pads of the fingers/toes, caused by immune complex deposition, and are a classic peripheral stigma of infective endocarditis.$x$, 1),
('c1000000-0000-0000-0000-000000000027', 'Janeway lesions are non-tender erythematous/haemorrhagic macules on the palms and soles, caused by septic microemboli.', 2),
('c1000000-0000-0000-0000-000000000027', 'Other peripheral stigmata include splinter haemorrhages, Roth spots (retinal), and clubbing in chronic disease.', 3),
('c1000000-0000-0000-0000-000000000028', 'Prosthetic valve endocarditis, especially with complications such as paravalvular abscess, heart failure, or persistent bacteraemia, is an indication for early surgical referral alongside prolonged targeted antibiotic therapy.', 1),
('c1000000-0000-0000-0000-000000000028', 'Coagulase-negative staphylococci are a recognised cause of prosthetic valve endocarditis, particularly within the first year after valve surgery.', 2),
('c1000000-0000-0000-0000-000000000028', 'Management should involve a multidisciplinary endocarditis team including microbiology and cardiac surgery, especially where surgical indications are present.', 3),
('c1000000-0000-0000-0000-000000000029', 'Indications for surgery in infective endocarditis include heart failure due to valve dysfunction, uncontrolled infection (persistent bacteraemia/fever despite appropriate antibiotics, abscess formation), and high risk of embolism.', 1),
('c1000000-0000-0000-0000-000000000029', 'Ongoing multidisciplinary team input (cardiology, microbiology, cardiac surgery) guides timing of intervention.', 2),
('c1000000-0000-0000-0000-000000000029', 'Antibiotic therapy alone is insufficient when structural valve damage causes haemodynamic compromise.', 3),
('c1000000-0000-0000-0000-000000000030', 'Current UK (NICE) guidance does not recommend routine antibiotic prophylaxis for dental procedures to prevent infective endocarditis, even in patients with prosthetic valves or other high-risk cardiac conditions.', 1),
('c1000000-0000-0000-0000-000000000030', 'Maintaining good oral hygiene and prompt treatment of dental infection is emphasised as the main preventive measure.', 2),
('c1000000-0000-0000-0000-000000000030', 'Patients at risk of endocarditis should be made aware of symptoms to report promptly, rather than relying on antibiotic prophylaxis.', 3),
('c1000000-0000-0000-0000-000000000031', 'Acute pericarditis presents with sharp chest pain relieved by sitting forward, a pericardial friction rub, and widespread saddle-shaped ST elevation with PR depression, distinguishing it from the territorial ST elevation of STEMI.', 1),
('c1000000-0000-0000-0000-000000000031', 'First-line treatment is NSAIDs combined with colchicine, which also reduces the risk of recurrence.', 2),
('c1000000-0000-0000-0000-000000000031', 'Corticosteroids are generally reserved as second-line therapy due to an association with higher recurrence rates.', 3),
('c1000000-0000-0000-0000-000000000032', $x$Cardiac tamponade presents with Beck's triad (hypotension, raised JVP, muffled heart sounds) and pulsus paradoxus; malignancy is a common cause of pericardial effusion leading to tamponade.$x$, 1),
('c1000000-0000-0000-0000-000000000032', 'Echocardiography rapidly confirms the diagnosis and guides emergency pericardiocentesis.', 2),
('c1000000-0000-0000-0000-000000000032', 'Diuretics and beta-blockers should be avoided as they can precipitate haemodynamic collapse by reducing preload or heart rate in a state dependent on tachycardia to maintain cardiac output.', 3),
('c1000000-0000-0000-0000-000000000033', 'Constrictive pericarditis results from pericardial thickening/fibrosis (tuberculosis is a classic cause worldwide) restricting diastolic filling, producing signs of systemic venous congestion.', 1),
('c1000000-0000-0000-0000-000000000033', $x$Kussmaul's sign (paradoxical rise in JVP with inspiration) is characteristic of constrictive pericarditis, unlike the pulsus paradoxus of tamponade.$x$, 2),
('c1000000-0000-0000-0000-000000000033', 'Diagnosis is supported by imaging showing pericardial thickening/calcification; management may require surgical pericardiectomy in symptomatic cases.', 3),
('c1000000-0000-0000-0000-000000000034', $x$Dressler's syndrome is an autoimmune pericarditis occurring typically 2-6 weeks after myocardial infarction, presenting with pleuritic chest pain, fever, and a pericardial effusion/friction rub.$x$, 1),
('c1000000-0000-0000-0000-000000000034', 'It is treated similarly to other forms of pericarditis, with NSAIDs (and colchicine).', 2),
('c1000000-0000-0000-0000-000000000034', 'It should be distinguished from recurrent ischaemia, which would typically present with different pain characteristics and ECG/troponin changes.', 3),
('c1000000-0000-0000-0000-000000000035', 'Pericarditis typically causes widespread, concave ST elevation that does not respect a single coronary territory, often with PR segment depression, whereas STEMI produces territorial ST elevation with reciprocal changes.', 1),
('c1000000-0000-0000-0000-000000000035', 'Reciprocal ST depression in leads opposite the affected territory strongly suggests STEMI rather than pericarditis.', 2),
('c1000000-0000-0000-0000-000000000035', 'Clinical context (pain relieved by sitting forward, preceding viral illness, pericardial rub) supports the diagnosis of pericarditis alongside these ECG features.', 3),
('c1000000-0000-0000-0000-000000000036', 'Hypothyroidism is a recognised cause of pericardial effusion, and effusions often improve with thyroid hormone replacement; malignancy is another important cause requiring separate management.', 1),
('c1000000-0000-0000-0000-000000000036', 'A haemodynamically stable patient with a large effusion but no signs of tamponade can often be managed conservatively with treatment of the underlying cause and close monitoring.', 2),
('c1000000-0000-0000-0000-000000000036', 'Pericardiocentesis (or surgical drainage) is reserved for diagnostic uncertainty, tamponade, or large/recurrent symptomatic effusions.', 3),
('c1000000-0000-0000-0000-000000000037', 'Aortic stenosis classically presents with the triad of exertional syncope, angina, and breathlessness, alongside a slow-rising pulse and an ejection systolic murmur radiating to the carotids.', 1),
('c1000000-0000-0000-0000-000000000037', 'Exertional syncope in aortic stenosis reflects fixed cardiac output failing to increase with the fall in systemic vascular resistance during exercise, and is a red flag for severe disease.', 2),
('c1000000-0000-0000-0000-000000000037', 'Severe symptomatic aortic stenosis requires specialist cardiology referral for consideration of valve replacement.', 3),
('c1000000-0000-0000-0000-000000000038', 'Mitral regurgitation produces a pansystolic murmur loudest at the apex, classically radiating to the axilla, and can result from ischaemic damage to the mitral valve apparatus.', 1),
('c1000000-0000-0000-0000-000000000038', 'A laterally displaced, hyperdynamic apex beat reflects left ventricular volume overload from chronic significant MR.', 2),
('c1000000-0000-0000-0000-000000000038', 'Assessment includes echocardiography to quantify severity and guide decisions about medical therapy versus surgical/percutaneous intervention.', 3),
('c1000000-0000-0000-0000-000000000039', 'Rheumatic heart disease (secondary to untreated group A streptococcal pharyngitis in childhood) remains the most common cause of mitral stenosis worldwide, particularly in areas with limited healthcare access.', 1),
('c1000000-0000-0000-0000-000000000039', 'Mitral stenosis classically causes a low-pitched, rumbling mid-diastolic murmur heard best at the apex in the left lateral position, and predisposes to atrial fibrillation due to left atrial enlargement.', 2),
('c1000000-0000-0000-0000-000000000039', 'Patients with mitral stenosis and AF are at increased thromboembolic risk and require anticoagulation.', 3),
('c1000000-0000-0000-0000-000000000040', 'Aortic regurgitation produces a wide pulse pressure and a collapsing (waterhammer) pulse due to rapid diastolic backflow into the left ventricle, with an early diastolic murmur best heard at the left sternal edge sitting forward.', 1),
('c1000000-0000-0000-0000-000000000040', 'Chronic AR can be caused by valve degeneration, bicuspid aortic valve, or aortic root disease.', 2),
('c1000000-0000-0000-0000-000000000040', 'Echocardiography assesses severity and left ventricular function, guiding timing of surgical intervention.', 3),
('c1000000-0000-0000-0000-000000000041', 'Acute severe aortic regurgitation (e.g. from endocarditis or aortic dissection) is poorly tolerated because the left ventricle has not had time to dilate/compensate, often causing rapid decompensation and pulmonary oedema.', 1),
('c1000000-0000-0000-0000-000000000041', 'This is a surgical emergency; valve surgery should not be delayed for a full antibiotic course when there is haemodynamic compromise.', 2),
('c1000000-0000-0000-0000-000000000041', 'An intra-aortic balloon pump is contraindicated in significant aortic regurgitation as it increases diastolic regurgitant flow.', 3),
('c1000000-0000-0000-0000-000000000042', 'Bicuspid aortic valve is associated with progressive valve dysfunction (stenosis and/or regurgitation) and aortic root/ascending aorta dilatation, increasing the risk of aortic dissection.', 1),
('c1000000-0000-0000-0000-000000000042', 'Regular surveillance imaging is required to monitor valve function and aortic dimensions, with surgical intervention considered if severity thresholds are reached.', 2),
('c1000000-0000-0000-0000-000000000042', 'First-degree relatives of patients with bicuspid aortic valve may also warrant screening given familial clustering.', 3),
('c1000000-0000-0000-0000-000000000043', 'Atrial septal defect causes left-to-right shunting, increasing right heart flow, which delays pulmonary valve closure; because the atria are effectively linked via the defect, splitting does not vary with respiration.', 1),
('c1000000-0000-0000-0000-000000000043', 'Patients with ASD may be asymptomatic for years, presenting in adulthood with exertional breathlessness, arrhythmias, or right heart failure.', 2),
('c1000000-0000-0000-0000-000000000043', 'Diagnosis is confirmed on echocardiography, and closure is considered for significant shunts to prevent long-term complications such as pulmonary hypertension.', 3),
('c1000000-0000-0000-0000-000000000044', 'Type A aortic dissection (involving the ascending aorta) is a surgical emergency due to the high risk of rupture, cardiac tamponade, and involvement of the coronary/carotid arteries; it requires urgent cardiothoracic surgery.', 1),
('c1000000-0000-0000-0000-000000000044', 'A difference in blood pressure between the arms, and tearing/ripping chest or back pain, are classic (though not universal) features of aortic dissection.', 2),
('c1000000-0000-0000-0000-000000000044', 'Thrombolysis must be avoided if dissection is suspected or confirmed, as it would precipitate catastrophic haemorrhage.', 3),
('c1000000-0000-0000-0000-000000000045', 'Type B aortic dissection (distal to the left subclavian artery, sparing the ascending aorta) is generally managed medically first-line, with tight blood pressure and heart rate control to reduce aortic wall stress.', 1),
('c1000000-0000-0000-0000-000000000045', 'Surgical or endovascular intervention for Type B dissection is reserved for complications such as malperfusion, rupture, or refractory pain/hypertension.', 2),
('c1000000-0000-0000-0000-000000000045', 'This contrasts with Type A dissection, which requires emergency surgery regardless of complications due to the high risk of catastrophic outcomes.', 3),
('c1000000-0000-0000-0000-000000000046', 'Ruptured AAA classically presents with sudden severe abdominal/back pain, hypotension, and a pulsatile abdominal mass; it is a surgical emergency requiring immediate senior vascular surgery involvement.', 1),
('c1000000-0000-0000-0000-000000000046', 'Permissive hypotension (avoiding aggressive fluid resuscitation to a fully normal blood pressure) is used en route to definitive repair to avoid worsening haemorrhage.', 2),
('c1000000-0000-0000-0000-000000000046', 'Unstable patients need immediate transfer to theatre without delay for extensive imaging if the diagnosis is clinically clear.', 3),
('c1000000-0000-0000-0000-000000000047', $x$Acute limb ischaemia presents with the '6 Ps': pain, pallor, pulselessness, paraesthesia, paralysis, and a perishingly cold limb; sensory/motor loss indicates a more advanced, time-critical presentation.$x$, 1),
('c1000000-0000-0000-0000-000000000047', 'Atrial fibrillation without anticoagulation is a common source of embolism causing acute limb ischaemia.', 2),
('c1000000-0000-0000-0000-000000000047', 'Immediate heparin anticoagulation and urgent vascular surgical assessment for revascularisation are required to prevent irreversible limb loss.', 3),
('c1000000-0000-0000-0000-000000000048', 'Massive (high-risk) pulmonary embolism is defined by haemodynamic instability (hypotension/shock) and carries a high mortality risk without prompt treatment.', 1),
('c1000000-0000-0000-0000-000000000048', 'Systemic thrombolysis is indicated in haemodynamically unstable PE (absent contraindications), aiming to rapidly reduce clot burden and right ventricular strain.', 2),
('c1000000-0000-0000-0000-000000000048', 'Post-operative status increases VTE risk; recognising PE as a cause of sudden collapse and hypoxia is essential, prompting urgent resuscitation and imaging.', 3),
('c1000000-0000-0000-0000-000000000049', 'Ventricular fibrillation is a shockable rhythm in cardiac arrest; immediate high-quality CPR and rapid unsynchronised defibrillation are the priorities, following the advanced life support algorithm.', 1),
('c1000000-0000-0000-0000-000000000049', 'Defibrillation should not be delayed to obtain IV access or give drugs; adrenaline and amiodarone are given at defined points in the algorithm alongside continued shocks and CPR.', 2),
('c1000000-0000-0000-0000-000000000049', 'Synchronised cardioversion is used for organised tachyarrhythmias with a pulse, not for pulseless VF/VT.', 3),
('c1000000-0000-0000-0000-000000000050', 'Post-cardiac arrest care includes airway/ventilation support, haemodynamic optimisation, targeted temperature management (avoiding hyperthermia), and identifying/treating the underlying cause.', 1),
('c1000000-0000-0000-0000-000000000050', 'ST elevation on the post-ROSC ECG should prompt urgent coronary angiography, regardless of consciousness level, as coronary occlusion is a common and treatable cause of arrest.', 2),
('c1000000-0000-0000-0000-000000000050', 'Neurological prognosis should not be determined in the immediate post-arrest period; decisions about angiography should not be withheld based on unconsciousness alone.', 3);
